css:
.wrap{ width: 100%; max-width: 1484px; margin-left: auto; margin-right: auto; padding-left: 40px; padding-right: 40px; box-sizing: border-box; }
.split{ display: grid; grid-template-columns: minmax(180px, 1fr) minmax(0, 920px); column-gap: 64px; row-gap: 24px; align-items: start; }
.split-body{ min-width: 0; }
.label{ margin: 0; font-family: Switzer, Arial, sans-serif; font-size: 18px; line-height: 1.25; font-weight: 500; letter-spacing: 0.04em; text-transform: uppercase; max-width: 320px; }
.lead{ margin: 0 0 32px 0; font-family: Switzer, Arial, sans-serif; font-size: 40px; line-height: 1.18; font-weight: 400; letter-spacing: -0.02em; }
.body-text{ margin: 0 0 16px 0; font-family: Switzer, Arial, sans-serif; font-size: 18px; line-height: 1.6; font-weight: 400; max-width: 760px; }
.button-pill{ display: inline-block; padding: 12px 24px; border: 1px solid currentColor; border-radius: 999px; font-family: Switzer, Arial, sans-serif; font-size: 17px; line-height: 1.3; font-weight: 400; color: inherit; text-decoration: none; white-space: nowrap; transition: background-color 0.2s ease, color 0.2s ease; }
.button-pill:hover{ background-color: rgba(128, 128, 128, 0.18); }
@media screen and (max-width: 991px){.split{ grid-template-columns: minmax(0, 1fr); row-gap: 20px; }
.lead{ font-size: 34px; }}
@media screen and (max-width: 767px){.wrap{ padding-left: 20px; padding-right: 20px; }
.label{ font-size: 15px; }
.lead{ font-size: 28px; margin-bottom: 24px; }
.body-text{ font-size: 17px; }}
@media screen and (max-width: 479px){.lead{ font-size: 25px; }
.button-pill{ font-size: 16px; padding: 11px 20px; white-space: normal; text-align: center; }}
.pi-section { padding-top: 150px; padding-bottom: 150px; background-color: #13181d; color: #ffffff; font-family: Switzer, Arial, sans-serif; scroll-margin-top: 120px; }
.pi-text-link { color: inherit; text-decoration: underline; text-underline-offset: 3px; }
.pi-text-link:hover { color: #9ae1fa; }
.pi-photos { display: grid; grid-template-columns: 539fr 560fr; gap: 20px; align-items: start; margin-top: 96px; padding-left: 0; margin-left: auto; max-width: 1140px; }
.pi-photo-albert { position: relative; aspect-ratio: 539 / 566; overflow: hidden; border-radius: 4px; }
.pi-photo-albert-img { display: block; width: 100%; height: 100%; object-fit: cover; object-position: 22% 50%; }
.pi-photo-room { position: relative; aspect-ratio: 560 / 420; overflow: hidden; border-radius: 4px; }
.pi-photo-room-img { display: block; width: 100%; height: 100%; object-fit: cover; object-position: 50% 100%; }
.pi-more { max-width: 920px; margin: 96px 0 0 auto; }
.pi-more-heading { margin: 0 0 24px 0; font-size: 28px; line-height: 1.15; font-weight: 500; letter-spacing: 0.01em; }

@media screen and (max-width: 991px) {
  .pi-section { padding-top: 112px; padding-bottom: 112px; }
  .pi-photos { margin-top: 64px; max-width: none; }
  .pi-more { margin-top: 72px; max-width: none; }
}
@media screen and (max-width: 767px) {
  .pi-section { padding-top: 88px; padding-bottom: 88px; }
  .pi-photos { grid-template-columns: minmax(0, 1fr); gap: 12px; margin-top: 48px; }
  .pi-photo-albert { aspect-ratio: 4 / 3; }
  .pi-more { margin-top: 56px; }
  .pi-more-heading { font-size: 24px; }
}
